.stat { display: flex; flex-direction: column; gap: var(--space-2); min-inline-size: 0; }
.stat-value {
  font-size: var(--font-2xl); font-weight: var(--font-weight-semibold);
  line-height: var(--leading-none); letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums; color: var(--foreground);
}
.stat[data-size="lg"] .stat-value { font-size: var(--font-3xl); }
.stat-unit { font-size: 0.55em; color: var(--muted-foreground); margin-inline-start: 0.1em; }
.stat-label { font-size: var(--font-xs); color: var(--muted-foreground); }

.stat[data-tone="primary"] .stat-value { color: var(--primary-accent); }
.stat[data-tone="success"] .stat-value { color: var(--success-emphasis); }
.stat[data-tone="warning"] .stat-value { color: var(--warning-emphasis); }
.stat[data-tone="ai"] .stat-value      { color: var(--ai); }

/* The comparison rides the value's baseline: it is read WITH the number, never
 * as a second fact under it. */
.stat-delta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin-inline-start: var(--space-2);
  font-size: var(--font-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: normal;
  color: var(--muted-foreground);
  vertical-align: middle;
}
.stat-delta[data-delta-tone="success"] { color: var(--success-emphasis); }
.stat-delta[data-delta-tone="danger"]  { color: var(--destructive-emphasis); }
/* THE TREND SITS AT THE FOOT OF THE CARD.
 *
 * Cards in a row are the same height (owner's rule, 23.08), so a KPI card
 * beside a chart card gets a lot of room. Two things were tried with it: leave
 * it as white under a 24px line (a hole), and stretch the trend into it (a
 * sparkline blown up to 300px, which is a different chart — the slopes come out
 * exaggerated because the shape is drawn without an aspect ratio). The spare
 * height goes BETWEEN the number and the trend instead: the value at the top,
 * the shape along the bottom, which is the KPI tile every dashboard draws. */
.stat-trend { margin-block-start: var(--space-1); }
.card > .stat { flex: 1 1 auto; }
/* The trend takes the spare height, up to a ceiling, and whatever is left over
 * goes ABOVE it — the value at the top of the tile, the shape along the bottom.
 * Both halves matter: without the growth a short card kept a 50px hole under
 * the label, and without the ceiling a tall one blew a 32px sparkline up to
 * 230px, which is a different chart (the shape is drawn without an aspect
 * ratio, so every slope came out exaggerated). */
.card > .stat > .stat-trend {
  flex: 1 1 auto;
  max-block-size: calc(var(--space-16) * 1.5);
  margin-block-start: auto;
  padding-block-start: var(--space-4);
  display: flex;
  align-items: stretch;
}
.card > .stat > .stat-trend > * { flex: 1 1 auto; block-size: auto; }

import "./Stat.css";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../lib/cn";
import { Icon, type IconName } from "../Icon";

type Tone = "neutral" | "primary" | "success" | "warning" | "ai";
type Size = "md" | "lg";
type DeltaDirection = "up" | "down" | "flat";
type DeltaTone = "success" | "danger" | "neutral";

type Props = HTMLAttributes<HTMLDivElement> & {
  /** The headline metric (rendered tabular-nums). */
  value: ReactNode;
  /** Caption under the value. */
  label: ReactNode;
  /** Semantic emphasis for the value. */
  tone?: Tone;
  /** Small suffix after the value, e.g. "/3" or "%". */
  unit?: string;
  /** The comparison that makes the value mean something: "+12% vs last week". */
  delta?: ReactNode;
  /** Which way it moved. Separate from `deltaTone` on purpose — up is good for
   *  revenue and bad for latency, so the arrow and the colour answer different
   *  questions. Named for the delta it describes, because `direction` alone was
   *  three different questions across the system (2026-08-26). */
  deltaDirection?: DeltaDirection;
  /** Whether that move is good news. Defaults to neutral, which colours nothing. */
  deltaTone?: DeltaTone;
  /** The shape behind the number: pass a <Sparkline>. */
  trend?: ReactNode;
  /** `md` in a row of tiles, `lg` for the one figure a screen is built around. A row where every
   *  tile is lg has no hierarchy.
   */
  size?: Size;
};

const ARROW: Record<DeltaDirection, IconName> = { up: "arrow_upward", down: "arrow_downward", flat: "remove" };

/** A KPI tile: a large value with a caption, and — when the number is judged
 *  rather than just read — the comparison and the trend behind it. Compose
 *  inside a <Card> for a bordered surface, or use bare in a <Grid>. 
 *
 * Copy: the label says what the number counts, with its unit and its period —
 * "Invoices paid this quarter". The delta says what it is compared to, or
 * it is not a comparison.
 */
export function Stat({
  value,
  label,
  tone = "neutral",
  unit,
  delta,
  deltaDirection,
  deltaTone = "neutral",
  trend,
  size,
  className,
  ...rest
}: Props) {
  return (
    <div className={cn("stat", className)} data-tone={tone} data-size={size} {...rest}>
      <div className="stat-value">
        {value}
        {unit && <span className="stat-unit">{unit}</span>}
        {delta != null && (
          <span className="stat-delta" data-delta-tone={deltaTone} data-delta-direction={deltaDirection}>
            {deltaDirection && <Icon name={ARROW[deltaDirection]} size="sm" />}
            {delta}
          </span>
        )}
      </div>
      <div className="stat-label">{label}</div>
      {trend && <div className="stat-trend">{trend}</div>}
    </div>
  );
}
